using ERPWMS.Database.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System;using System.Linq;using System.Security.Claims;using System.Threading.Tasks;
using ERPWMS.Database;
namespace ERPWMS.Controllers.Workflow{[Authorize]public class WorkflowAssignmentController:Controller{private readonly AppDbContext _context;public WorkflowAssignmentController(AppDbContext c){_context=c;}
private int Uid()
        {
            var cl = User.FindFirstValue(ClaimTypes.NameIdentifier);
            if (!int.TryParse(cl, out var i) || i <= 0)
                throw new UnauthorizedAccessException("User identity missing.");
            return i;
        }
[HttpGet]public IActionResult Index()=>View();
[HttpGet]public async Task<IActionResult> GetStatistics(){var l=await _context.WorkflowAssignments.ToListAsync();return Json(new{total=l.Count,active=l.Count(a=>a.IsActive == true),inactive=l.Count(a=>a.IsActive!=true),addedThisMonth=l.Count(a=>a.CreatedDate.HasValue&&a.CreatedDate.Value.Month==DateTime.Now.Month&&a.CreatedDate.Value.Year==DateTime.Now.Year)});}
[HttpGet]public async Task<IActionResult> GetAll(){var l=await _context.WorkflowAssignments.Include(a=>a.WorkflowDef).Include(a=>a.Stage).Where(a=>a.IsActive!=false).OrderBy(a => a.AssignmentId).Select(a=>new{assignmentId=a.AssignmentId,workflowName=a.WorkflowDef!=null?a.WorkflowDef.WorkflowName:"-",stageName=a.Stage!=null?a.Stage.StageName:"-",roleName=a.Role!=null?a.Role.Name:"-",userName=a.User!=null?a.User.UserName:"-",canApprove=a.CanApprove??false,canReject=a.CanReject??false,isActive=a.IsActive??false,createdDate=a.CreatedDate}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetWorkflows(){var l=await _context.WorkflowDefinitions.Where(d=>d.IsActive == true&&d.IsDeleted!=true).Select(d=>new{workflowDefId=d.WorkflowDefId,workflowName=d.WorkflowName}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetStages(int workflowDefId){var l=await _context.WorkflowStages.Where(s=>s.WorkflowDefId==workflowDefId&&s.IsDeleted!=true).Select(s=>new{stageId=s.StageId,stageName=s.StageName}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetRoles(){var l=await _context.AspNetRoles.Select(r=>new{roleId=r.Id,roleName=r.Name}).ToListAsync();return Json(l);}
[HttpGet]public async Task<IActionResult> GetUsers(){var l=await _context.Users.Select(u=>new{userId=u.Id,userName=u.UserName}).Take(500).ToListAsync();return Json(l);}
[HttpGet]public IActionResult AddPartial()=>PartialView("_AddForm");
[HttpGet]public async Task<IActionResult> EditPartial(int id){var a=await _context.WorkflowAssignments.FindAsync(id);if(a==null)return NotFound();return PartialView("_EditForm",a);}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Register(int workflowDefId,int stageId,int? roleId,int? userId,bool canApprove,bool canReject,bool canHold,bool canSendBack){try{if(workflowDefId<=0||stageId<=0)return Json(new{success=false,message="Workflow and stage required."});_context.WorkflowAssignments.Add(new WorkflowAssignment{WorkflowDefId=workflowDefId,StageId=stageId,RoleId=roleId,UserId=userId,CanApprove=canApprove,CanReject=canReject,CanHold=canHold,CanSendBack=canSendBack,IsActive=true,CreatedBy=Uid().ToString(),CreatedDate=DateTime.Now});await _context.SaveChangesAsync();return Json(new{success=true,message="Assignment created!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Edit(int assignmentId,int? roleId,int? userId,bool canApprove,bool canReject,bool canHold,bool canSendBack,bool isActive=true){try{var a=await _context.WorkflowAssignments.FindAsync(assignmentId);if(a==null)return Json(new{success=false});a.RoleId=roleId;a.UserId=userId;a.CanApprove=canApprove;a.CanReject=canReject;a.CanHold=canHold;a.CanSendBack=canSendBack;a.IsActive=isActive;a.UpdatedBy=Uid().ToString();a.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Assignment updated!"});}catch(Exception ex){return Json(new{success=false,message=(ex.InnerException??ex).Message});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Delete(int id){try{var a=await _context.WorkflowAssignments.FindAsync(id);if(a==null)return Json(new{success=false});a.IsActive=false;a.UpdatedBy=Uid().ToString();a.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message="Deleted."});}catch(Exception ex){return Json(new{success=false,message = "Operation failed."});}}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Toggle(int id){try{var a=await _context.WorkflowAssignments.FindAsync(id);if(a==null)return Json(new{success=false});a.IsActive=!(a.IsActive??false);a.UpdatedBy=Uid().ToString();a.UpdatedDate=DateTime.Now;await _context.SaveChangesAsync();return Json(new{success=true,message=a.IsActive == true?"Activated.":"Deactivated."});}catch(Exception ex){return Json(new{success=false,message = "Operation failed."});}}
}}

